// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.llm.cloudimport com.roshan.persona.brain.llm.provider.ApiProtocolimport com.roshan.persona.brain.llm.provider.CloudLlmProviderimport com.roshan.persona.brain.llm.provider.CloudProviderConfigimport com.roshan.persona.brain.llm.provider.GenerationConfigimport com.roshan.persona.brain.llm.provider.GenerationResultimport com.roshan.persona.brain.llm.provider.FinishReasonimport com.roshan.persona.brain.llm.provider.ModelInfoimport com.roshan.persona.brain.llm.provider.Pricingimport com.roshan.persona.brain.stream.CancellationTokenimport com.roshan.persona.common.Resultimport com.roshan.persona.brain.skill.CredentialVaultInterfaceimport kotlinx.coroutines.Dispatchersimport kotlinx.coroutines.withContextimport okhttp3.MediaType.Companion.toMediaTypeimport okhttp3.OkHttpClientimport okhttp3.Requestimport okhttp3.RequestBody.Companion.toRequestBodyimport timber.log.Timberimport com.roshan.persona.common.AppErrorimport com.roshan.persona.common.CorrelationId/** * NOUS — OkHttp Cloud LLM Provider. * * Implements [CloudLlmProvider] (defined in Brain Module 2) using OkHttp. * Supports OpenAI-compatible, Anthropic, and Gemini APIs. * * v2.1 Review 2 Fix #10: PII scrubbing SENDS scrubbed version to cloud * (not original). The caller is responsible for scrubbing — this provider * receives already-scrubbed prompts. * * v2.1 Fix #5: Barge-in via `call.cancel()` — when CancellationToken is * cancelled, the underlying HTTP call is immediately aborted. * * @see <a href="docs/strategy/module-4-strategy-v2.1.md">§7 OkHttpCloudProvider</a> */class OkHttpCloudProvider(    override val config: CloudProviderConfig,    private val httpClient: OkHttpClient,    private val credentialVault: CredentialVaultInterface,    private val streamParser: StreamParser = StreamParser(),) : CloudLlmProvider {    override val providerId: String get() = config.id    override val displayName: String get() = config.displayName    override val isAvailable: Boolean        get() = config.isEnabled && getApiKey() != null    /**     * Generate text from a prompt with streaming token callback.     *     * v2.1: Prompt should be ALREADY scrubbed of PII by caller.     * v2.1: Barge-in via call.cancel() when CancellationToken is cancelled.     */    override suspend fun generate(        prompt: String,        model: String,        generationConfig: GenerationConfig,        onToken: (String) -> Unit,        cancellationToken: CancellationToken?,    ): Result<GenerationResult> {        if (!isAvailable) {            return Result.Failure(AppError.from(IllegalStateException("Provider not available: ${this.config.id}")), CorrelationId.generate(), 0)        }        val apiKey = getApiKey()            ?: return Result.Failure(AppError.from(IllegalStateException("API key not found in credential vault")), CorrelationId.generate(), 0)        return withContext(Dispatchers.IO) {            try {                val startTime = System.nanoTime()                val request = buildRequest(prompt, model, generationConfig, apiKey)                // Execute request                val call = httpClient.newCall(request)                // v2.1: Barge-in — cancel HTTP call when token is cancelled                cancellationToken?.let { token ->                    if (token.isCancelled) {                        call.cancel()                        return@withContext Result.Failure(AppError.from(                            IllegalStateException("Cancelled before start")                        ), CorrelationId.generate(), 0)                    }                }                val response = call.execute()                if (!response.isSuccessful) {                    val errorBody = response.body?.string() ?: "Unknown error"                    Timber.e("Cloud LLM error: ${response.code} — $errorBody")                    return@withContext Result.Failure(AppError.from(                        IllegalStateException("HTTP ${response.code}: $errorBody")                    ), CorrelationId.generate(), 0)                }                // Parse streaming response                val fullText = StringBuilder()                val responseBody = response.body ?: return@withContext Result.Failure(AppError.from(                    IllegalStateException("Empty response body")                ), CorrelationId.generate(), 0)                // Anthropic streams use TWO lines per event:                //   event: content_block_delta                //   data: {"type":"content_block_delta","delta":{"type":"text_delta","text":"Hello"}}                // We track the last seen `event:` line and pair it with the next `data:`.                var pendingAnthropicEvent: String? = null                responseBody.source().use { source ->                    while (!source.exhausted()) {                        val line = source.readUtf8Line() ?: break                        // Check for barge-in during streaming                        if (cancellationToken?.isCancelled == true) {                            call.cancel()                            break                        }                        // Anthropic: track event type                        if (config.apiProtocol == ApiProtocol.ANTHROPIC && line.startsWith("event: ")) {                            pendingAnthropicEvent = line.removePrefix("event: ").trim()                            continue                        }                        if (line.startsWith("data: ")) {                            val data = line.removePrefix("data: ")                            if (streamParser.isStreamEnd(data)) break                            val token = when (config.apiProtocol) {                                ApiProtocol.ANTHROPIC ->                                    streamParser.parseAnthropicToken(pendingAnthropicEvent ?: "content_block_delta", data)                                ApiProtocol.GEMINI -> streamParser.parseGeminiToken(data)                                else -> streamParser.parseToken(data)                            }                            if (token != null) {                                fullText.append(token)                                onToken(token)                            }                            // Reset pending event after consuming its data line                            if (config.apiProtocol == ApiProtocol.ANTHROPIC) {                                pendingAnthropicEvent = null                            }                        }                    }                }                val durationMs = (System.nanoTime() - startTime) / 1_000_000                val tokensGenerated = fullText.length / 4  // rough estimate                val costUsd = config.pricingPer1kTokens.let {                    (tokensGenerated.toFloat() / 1000f) * it.outputPer1k +                        (prompt.length / 4f / 1000f) * it.inputPer1k                }                Result.Success(GenerationResult(                    text = fullText.toString(),                    tokensGenerated = tokensGenerated,                    tokensPerSecond = if (durationMs > 0) tokensGenerated.toFloat() / durationMs * 1000 else 0f,                    durationMs = durationMs,                    finishReason = if (cancellationToken?.isCancelled == true) FinishReason.STOP                                   else FinishReason.STOP,                    promptTokens = prompt.length / 4,                    modelId = model,                ), CorrelationId.generate(), 0)            } catch (e: Exception) {                Timber.e(e, "Cloud LLM generation failed: ${config.id}")                Result.Failure(AppError.from(e), CorrelationId.generate(), 0)            }        }    }    override suspend fun embed(text: String, model: String?): Result<FloatArray> {        // Not all providers support embeddings — return failure for now        return Result.Failure(AppError.from(UnsupportedOperationException("Embeddings not supported for ${config.id}")), CorrelationId.generate(), 0)    }    override suspend fun validateCredentials(): Result<Unit> {        val apiKey = getApiKey()            ?: return Result.Failure(AppError.from(IllegalStateException("API key not found")), CorrelationId.generate(), 0)        return withContext(Dispatchers.IO) {            try {                val request = Request.Builder()                    .url("${config.baseUrl}/models")                    .header("Authorization", "Bearer $apiKey")                    .get()                    .build()                val response = httpClient.newCall(request).execute()                if (response.isSuccessful) {                    Result.Success(Unit, CorrelationId.generate(), 0)                } else {                    Result.Failure(AppError.from(IllegalStateException("HTTP ${response.code}")), CorrelationId.generate(), 0)                }            } catch (e: Exception) {                Result.Failure(AppError.from(e), CorrelationId.generate(), 0)            }        }    }    override suspend fun listAvailableModels(): Result<List<ModelInfo>> {        return Result.Failure(AppError.from(UnsupportedOperationException("Model listing not implemented for ${config.id}")), CorrelationId.generate(), 0)    }    // ─── Private helpers ─────────────────────────────────────────────    private fun getApiKey(): String? {        // CredentialVaultInterface.getCredential(skillId, key) — use provider id        // as the skillId and the configured apiKeyAlias as the key.        return credentialVault.getCredential(config.id, config.apiKeyAlias)    }    private fun buildRequest(        prompt: String,        model: String,        generationConfig: GenerationConfig,        apiKey: String,    ): Request {        val jsonBody = when (this.config.apiProtocol) {            ApiProtocol.OPENAI_COMPATIBLE -> {                """{"model":"$model","messages":[{"role":"user","content":"$prompt"}],"temperature":${generationConfig.temperature},"max_tokens":${generationConfig.maxTokens},"stream":true}"""            }            ApiProtocol.ANTHROPIC -> {                """{"model":"$model","messages":[{"role":"user","content":"$prompt"}],"max_tokens":${generationConfig.maxTokens},"stream":true}"""            }            ApiProtocol.GEMINI -> {                """{"contents":[{"parts":[{"text":"$prompt"}]}],"generationConfig":{"temperature":${generationConfig.temperature},"maxOutputTokens":${generationConfig.maxTokens}}}"""            }        }        val mediaType = "application/json".toMediaType()        val body = jsonBody.toRequestBody(mediaType)        val requestBuilder = Request.Builder()            .url(getEndpointUrl(model, apiKey))            .post(body)            .header("Content-Type", "application/json")        // Per-protocol auth:        //   OpenAI / Groq / OpenRouter → Authorization: Bearer <key>        //   Anthropic                  → x-api-key: <key> + anthropic-version: 2023-06-01        //   Gemini                     → ?key=<key> URL param (header set below for fallback)        when (this.config.apiProtocol) {            ApiProtocol.ANTHROPIC -> {                requestBuilder.header("x-api-key", apiKey)                requestBuilder.header("anthropic-version", "2023-06-01")            }            ApiProtocol.GEMINI -> {                // Already added as ?key= in URL; also set x-goog-api-key for redundancy                requestBuilder.header("x-goog-api-key", apiKey)            }            ApiProtocol.OPENAI_COMPATIBLE -> {                requestBuilder.header("Authorization", "Bearer $apiKey")            }        }        // Add custom headers        for ((key, value) in this.config.customHeaders) {            requestBuilder.header(key, value)        }        return requestBuilder.build()    }    private fun getEndpointUrl(model: String, apiKey: String): String {        return when (this.config.apiProtocol) {            ApiProtocol.OPENAI_COMPATIBLE -> "${config.baseUrl}/chat/completions"            ApiProtocol.ANTHROPIC -> "${config.baseUrl}/v1/messages"            ApiProtocol.GEMINI -> "${config.baseUrl}/v1beta/models/$model:streamGenerateContent?key=$apiKey"        }    }}